def standard():
    from itertools import product
    k = sum(1 for t in product(range(1, 5), repeat=5) if (t[0]*t[1]*t[2]*t[3]*t[4]) % 6 == 0)
    v = Fraction(k, 4**5)
    return v.numerator + v.denominator

def unique():
    return [standard()]
